-- Horizontal Partitioning Example (Range)
CREATE TABLE orders (id INT, order_date DATE, data TEXT)
PARTITION BY RANGE (YEAR(order_date)) (
    PARTITION p2022 VALUES LESS THAN (2023),
    PARTITION p2023 VALUES LESS THAN (2024)
);

-- Vertical Partitioning Example
-- Move heavy 'biography' and 'profile_picture' to a separate table
CREATE TABLE user_profiles (user_id INT PRIMARY KEY, bio TEXT, photo_blob BLOB);
CREATE TABLE users (user_id INT PRIMARY KEY, username VARCHAR(50), email VARCHAR(100));
